OUTPUT_SUBGRID_COLORS = {
    (0, 0): 2,  # from test (0,0)
    (0, 1): 3,  # from test (1,0)
    (0, 2): 4,  # from test (2,0)
    (0, 3): 6,  # from test (3,0)
    (0, 4): 7,  # from test (4,0)
    (2, 1): 1,  # from test (1,2) - cross pattern
    # (1, 0) has no corresponding test subgrid -> empty
}

def get_subgrid_idx_for_output(r_out, c_out):
    """Get color for output subgrid (r_out, c_out)"""
    return OUTPUT_SUBGRID_COLORS.get((r_out, c_out), 0)

def build_subgrid_pattern(color):
    """Build a 4x4 subgrid pattern with 2x2 filled block at (1,1)"""
    pattern = [[0]*4 for _ in range(4)]
    pattern[1][1] = color
    pattern[1][2] = color
    pattern[2][1] = color
    pattern[2][2] = color
    return pattern

def build_output_grid():
    """Build the full 24x24 output grid"""
    grid = []
    for r_out in range(24):
        row_vals = []
        r_out_sub = r_out // 5
        is_beeline_row = r_out in {4, 9, 14, 19}

        for c_out in range(24):
            c_out_sub = c_out // 5
            is_beeline_col = c_out in {4, 9, 14, 19}

            if is_beeline_row or is_beeline_col:
                row_vals.append(5)
            else:
                color = get_subgrid_idx_for_output(r_out_sub, c_out_sub)
                if color != 0:
                    # Get the cell value from the subgrid pattern
                    r_in_sub = r_out % 5
                    c_in_sub = c_out % 5
                    if not is_beeline_row and not is_beeline_col:
                        # Get color from pattern
                        pattern = build_subgrid_pattern(color)
                        row_vals.append(pattern[r_in_sub][c_in_sub] if r_in_sub < 4 and c_in_sub < 4 else 0)
                    else:
                        row_vals.append(0)
                else:
                    row_vals.append(0)
        grid.append(row_vals)
    return grid

def build_output_grid_v2():
    """Simpler version based on what we know"""
    grid = []
    for r in range(24):
        row_vals = []
        for c in range(24):
            is_beeline = (r in {4, 9, 14, 19}) or (c in {4, 9, 14, 19})
            if is_beeline:
                row_vals.append(5)
            else:
                r_sub = r // 5
                c_sub = c // 5
                color = get_subgrid_idx_for_output(r_sub, c_sub)

                if color == 0:
                    row_vals.append(0)
                elif (r_sub, c_sub) == (2, 1):
                    # Cross pattern for (2,1)
                    r_in = r % 5
                    c_in = c % 5
                    # Center cross around subgrid (1,1)
                    if r_in == 1 or r_in == 2:
                        if c_in == 1 or c_in == 2:
                            row_vals.append(1)
                    else:
                        row_vals.append(0)
                else:
                    # 2x2 fill pattern
                    r_in = r % 5
                    c_in = c % 5
                    if 1 <= r_in <= 2 and 1 <= c_in <= 2:
                        row_vals.append(color)
                    else:
                        row_vals.append(0)
        grid.append(row_vals)
    return grid

output = build_output_grid_v2()
print(json.dumps(output))

